// Bina HiveMQ ke test: simulated reading banao (har 5th reading leak)
let count = flow.get('count') || 0;
let prev = flow.get('prev_pressure');
let leak = (count % 5 === 4);
let p = leak ? 5.0 + Math.random() * 1.0 : 6.8 + Math.random() * 0.7;
let t = leak ? 55 + Math.random() * 10 : 35 + Math.random() * 15;
let f = leak ? 250 + Math.random() * 50 : 180 + Math.random() * 40;
flow.set('count', count + 1);
msg.payload = {
  timestamp: new Date().toISOString(),
  pressure: Math.round(p * 100) / 100,
  temperature: Math.round(t * 10) / 10,
  flow: Math.round(f * 10) / 10
};
return msg;

// Leakage logic - Python wale synthetic_data.py jaisi hi (score-based)
let p = msg.payload.pressure;
let t = msg.payload.temperature;
let f = msg.payload.flow;
let prev = flow.get('prev_pressure');
let score = 0, reasons = [];
if (p < 6.2) { score += 2; reasons.push('Pressure low: ' + p + ' bar (< 6.2)'); }
if (prev !== undefined && (prev - p) > 0.8) { score += 2; reasons.push('Sudden drop: ' + prev + ' -> ' + p + ' bar'); }
if (f > 240) { score += 1; reasons.push('Flow high: ' + f + ' L/min (> 240)'); }
if (t > 55) { score += 1; reasons.push('Temp high: ' + t + ' C (> 55)'); }
flow.set('prev_pressure', p);
msg.payload.leakage = score >= 3 ? 'Possible Leakage' : score === 2 ? 'Warning' : 'Normal';
msg.payload.reason = reasons.join('; ');
return msg;
